<?php
namespace App\Services;
use App\Models\Upload;
use Illuminate\Support\Facades\DB;
class UnusedImageCleaner {
 // Fail closed: search every base table's scalar/text columns before quarantining an upload.
 public static function referenced($u,$includeId=true,array $ignoreTables=[],array $additionalFiles=[]){$id=(string)$u->id;$file=(string)$u->file_name;$files=array_values(array_unique(array_merge([$file],$additionalFiles)));foreach(DB::select('SHOW FULL TABLES')as $tableRow){$values=array_values((array)$tableRow);if(($values[1]??'')!=='BASE TABLE')continue;$table=$values[0];if($table==='uploads'||in_array($table,$ignoreTables,true))continue;$columns=DB::getSchemaBuilder()->getColumnListing($table);$query=DB::table($table)->where(function($q)use($columns,$id,$file,$includeId,$files){foreach($columns as $column){$quoted='`'.str_replace('`','``',$column).'`';foreach($files as $one)foreach(array_unique([$one,str_replace('/','\\/',$one),rawurlencode($one)])as $needle)$q->orWhereRaw('CAST('.$quoted." AS CHAR) LIKE ? ESCAPE '!'", ['%'.strtr($needle,['!'=>'!!','%'=>'!%','_'=>'!_']).'%']);if($includeId&&preg_match('/photo|image|logo|banner|icon|avatar|thumbnail|gallery|attachment|file|media|value|content|description|setting|data/i',$column))$q->orWhereRaw('CAST('.$quoted.' AS CHAR) REGEXP ?',['(^|[^0-9])'.$id.'([^0-9]|$)']);}});if($table==='business_settings')$query->whereRaw("type NOT LIKE 'ops!_%' ESCAPE '!'");if($query->exists())return true;} // Version archives and settings can contain encrypted references, so retain all protected version assets.
 // Original/version assets referenced by product settings remain protected by the checks above.
 foreach(['inbox_messages'=>['payload'],'website_chat_threads'=>['product_context'],'inbox_order_drafts'=>['details']] as $table=>$fields){if(!DB::getSchemaBuilder()->hasTable($table))continue;foreach($fields as $field){if(!DB::getSchemaBuilder()->hasColumn($table,$field))continue;foreach(DB::table($table)->whereNotNull($field)->orderBy('id')->select(['id',$field])->cursor() as $row){if($row->$field==='')continue;$raw=\Illuminate\Support\Facades\Crypt::decryptString($row->$field);$decoded=json_decode($raw,true);$text=$decoded===null?$raw:json_encode($decoded,JSON_UNESCAPED_SLASHES);foreach($files as $one)if(strpos($text,$one)!==false)return true;}}}
 foreach(\App\Models\BusinessSetting::where('type','like','ops_%')->where('type','!=','ops_audit')->get()as $row){$value=\Illuminate\Support\Facades\Crypt::decryptString($row->value);if(self::containsFile($value,$files)||($includeId&&preg_match('/(?:["\[:,])\s*"?'.preg_quote($id,'/').'"?\s*(?:[,\]}])/',$value)))return true;}return false;}
 private static function containsFile($text,array $files){$text=str_replace('\\/','/',rawurldecode((string)$text));foreach($files as $file)if(strpos($text,$file)!==false)return true;return false;}
 public static function path($u){$root=realpath(public_path('uploads'));$path=realpath(public_path($u->file_name));abort_unless($root&&$path&&is_file($path)&&!is_link($path)&&strpos(str_replace('\\','/',$path),rtrim(str_replace('\\','/',$root),'/').'/')===0,422,'Local image required.');return $path;}
 public static function quarantined(){ $rows=[];foreach(glob(storage_path('app/image-quarantine/*.json'))?:[]as $file){$m=json_decode((string)file_get_contents($file),true);if(is_array($m))$rows[]=['reference'=>basename($file,'.json'),'id'=>$m['id']??null,'at'=>$m['at']??null];}return array_slice(array_reverse($rows),0,100);}
 public static function scan($after=0){$out=[];$items=Upload::where('type','image')->where('id','>',$after)->orderBy('id')->limit(3)->get();foreach($items as $u){try{$path=self::path($u);if(!self::referenced($u))$out[]=['id'=>$u->id,'name'=>$u->file_original_name,'url'=>my_asset($u->file_name),'bytes'=>filesize($path)];}catch(\Throwable $e){/* uncertain assets retained */}}$next=$items->last()->id??$after;return ['items'=>$out,'next'=>$next,'done'=>$items->count()<3,'total'=>Upload::where('type','image')->count(),'scanned'=>Upload::where('type','image')->where('id','<=',$next)->count()];}
 public static function quarantine($id,array $ignoreTables=[],$withTrashed=false,array $additionalFiles=[]){$u=($withTrashed?Upload::withTrashed():Upload::query())->findOrFail($id);$path=self::path($u);abort_if(self::referenced($u,true,$ignoreTables,$additionalFiles),409,'Image is referenced or protected; retained.');abort_if(Upload::where('file_name',$u->file_name)->where('id','!=',$id)->exists(),409,'Shared upload file; retained.');$dir=storage_path('app/image-quarantine');if(!is_dir($dir))mkdir($dir,0700,true);$entry=$dir.'/'.$id.'-'.bin2hex(random_bytes(8));$meta=['id'=>$id,'file'=>$u->file_name,'sha256'=>hash_file('sha256',$path),'at'=>now()->toIso8601String()];file_put_contents($entry.'.json',json_encode($meta),LOCK_EX);if(!rename($path,$entry.'.image')){unlink($entry.'.json');throw new \RuntimeException('Quarantine move failed.');}@chmod($entry.'.image',0600);StoreOperations::audit('image_quarantined:'.$id);return ['ok'=>true,'reference'=>basename($entry)];}
 public static function restore($reference,$withTrashed=false){abort_unless(preg_match('/^[0-9]+-[a-f0-9]{16}$/D',$reference),422);$base=storage_path('app/image-quarantine/'.$reference);$meta=json_decode((string)@file_get_contents($base.'.json'),true);abort_unless($meta&&is_file($base.'.image')&&hash_equals($meta['sha256'],hash_file('sha256',$base.'.image')),422);$u=($withTrashed?Upload::withTrashed():Upload::query())->findOrFail($meta['id']);abort_unless($u->file_name===$meta['file']&&strpos($u->file_name,'uploads/')===0&&strpos($u->file_name,'..')===false,422);$dest=public_path($u->file_name);abort_if(file_exists($dest),409,'Destination exists.');if(!is_dir(dirname($dest)))mkdir(dirname($dest),0755,true);abort_unless(rename($base.'.image',$dest),500);@chmod($dest,0644);unlink($base.'.json');return ['ok'=>true];}

 public static function permanent($reference,array $ignoreTables=[],$withTrashed=false,array $additionalFiles=[]){abort_unless(preg_match('/^[0-9]+-[a-f0-9]{16}$/D',$reference),422);$base=storage_path('app/image-quarantine/'.$reference);$meta=json_decode((string)@file_get_contents($base.'.json'),true);abort_unless($meta&&is_file($base.'.image')&&hash_equals($meta['sha256'],hash_file('sha256',$base.'.image')),422,'Trash record is missing or damaged.');$u=($withTrashed?Upload::withTrashed():Upload::query())->findOrFail($meta['id']);abort_unless($u->file_name===$meta['file'],409);abort_if(self::referenced($u,true,$ignoreTables,$additionalFiles),409,'Media is referenced now; permanent deletion blocked.');abort_if(Upload::where('file_name',$u->file_name)->where('id','!=',$u->id)->exists(),409,'Shared media retained.');abort_unless(unlink($base.'.image'),500);$u->forceDelete();@unlink($base.'.json');StoreOperations::audit('unused_media_permanently_deleted:'.$meta['id']);return ['ok'=>true];}

 public static function quarantinedIds(){ $ids=[];foreach(glob(storage_path('app/image-quarantine/*.json'))?:[] as $p)if(preg_match('/^([0-9]+)-[a-f0-9]{16}\.json$/D',basename($p),$m))$ids[]=(int)$m[1];return array_values(array_unique($ids));}
}
